SELECT account_type, CASE WHEN balance >= 73000 THEN 'high' WHEN balance >= 36000 THEN 'mid' ELSE 'low' END AS balance_bucket, SUM(balance) AS total_balance, ROUND(AVG(balance), 2) AS avg_balance FROM accounts WHERE (opened_date BETWEEN '2023-07-12' AND '2024-07-01' AND balance > 74000) OR balance BETWEEN 23000 AND 36000 GROUP BY account_type, CASE WHEN balance >= 73000 THEN 'high' WHEN balance >= 36000 THEN 'mid' ELSE 'low' END ORDER BY avg_balance, account_type, balance_bucket LIMIT 5;
